/*
# Seed welfare schemes catalog

## Overview
Populates the schemes table with a curated catalog of representative government
welfare programs across categories. Adds a unique constraint on schemes.title
to make the seed idempotent via ON CONFLICT (title) DO NOTHING.

## Security
No security changes.

## Notes
1. Idempotent: unique constraint on title + ON CONFLICT DO NOTHING.
*/

CREATE UNIQUE INDEX IF NOT EXISTS schemes_title_unique ON schemes(title);

ON CONFLICT (title) DO NOTHING;
